// src/GDAL7_open.cpp
// Manual file - NOT generated by orchestrate.R
// Provides gdal_open() to create Dataset objects

#include <cpp11.hpp>
#include <gdal.h>

[[cpp11::register]]
SEXP GDAL7_gdal_open(std::string path, bool update) {
  // Ensure GDAL is initialized
  GDALAllRegister();

  unsigned int flags = update ? GDAL_OF_UPDATE : GDAL_OF_READONLY;
  flags |= GDAL_OF_VERBOSE_ERROR;

  GDALDatasetH h = GDALOpenEx(path.c_str(), flags, nullptr, nullptr, nullptr);
  if (!h) {
    cpp11::stop("Failed to open: %s", path.c_str());
  }

  return cpp11::external_pointer<GDALDatasetH>(new GDALDatasetH(h));
}

[[cpp11::register]]
void GDAL7_close(SEXP xp) {
  // Get the external pointer and close the dataset
  GDALDatasetH* ptr = reinterpret_cast<GDALDatasetH*>(R_ExternalPtrAddr(xp));
  if (ptr && *ptr) {
    GDALClose(*ptr);
    *ptr = nullptr;
  }
}
